"use client";

import React, { useState, useRef, useMemo } from "react";
import FullCalendar from "@fullcalendar/react";
import dayGridPlugin from "@fullcalendar/daygrid";
import interactionPlugin from "@fullcalendar/interaction";
import { 
  Calendar as CalendarIcon, ChevronLeft, ChevronRight, 
  Sparkles, MapPin, ChevronDown, CalendarDays, Clock
} from "lucide-react";

// --- CONFIGURATION ---
const HOLIDAYS = [
  { id: "h1", title: "Republic Day", start: "2026-01-26", type: "holiday" },
  { id: "h2", title: "Valentine's Day", start: "2026-02-14", type: "holiday" },
];

const MY_LEAVES = [
  { id: "l1", title: "Annual Leave", start: "2026-02-10", end: "2026-02-13", type: "leave" },
  { id: "l2", title: "Sick Day", start: "2026-01-15", type: "leave" }
];

const MONTHS = ["January", "February", "March", "April", "May", "June", "July", "August", "September", "October", "November", "December"];

export default function EliteCalendarPro() {
  const calendarRef = useRef<FullCalendar>(null);
  const [currentDate, setCurrentDate] = useState(new Date());

  // --- HANDLERS ---
  const handlePrev = () => {
    const api = calendarRef.current?.getApi();
    api?.prev();
    if(api) setCurrentDate(api.getDate());
  };

  const handleNext = () => {
    const api = calendarRef.current?.getApi();
    api?.next();
    if(api) setCurrentDate(api.getDate());
  };

  const handleToday = () => {
    const api = calendarRef.current?.getApi();
    api?.today();
    if(api) setCurrentDate(api.getDate());
  };

  const handleMonthChange = (e: React.ChangeEvent<HTMLSelectElement>) => {
    const date = new Date(currentDate);
    date.setMonth(parseInt(e.target.value));
    calendarRef.current?.getApi().gotoDate(date);
    setCurrentDate(date);
  };

  const handleYearChange = (e: React.ChangeEvent<HTMLSelectElement>) => {
    const date = new Date(currentDate);
    date.setFullYear(parseInt(e.target.value));
    calendarRef.current?.getApi().gotoDate(date);
    setCurrentDate(date);
  };

  // --- CUSTOM EVENT CARD ---
  const renderEvent = (info: any) => {
    const isHoliday = info.event.extendedProps.type === 'holiday';
    return (
      <div className={`group flex items-center gap-2 px-2 py-1.5 rounded-lg mb-1.5 w-full transition-all hover:scale-[1.02] cursor-pointer shadow-sm border-l-[3px] ${
        isHoliday 
          ? "bg-emerald-50/80 border-emerald-500 text-emerald-800" 
          : "bg-indigo-50/80 border-indigo-500 text-indigo-800"
      }`}>
        {isHoliday ? <Sparkles size={10} className="shrink-0 opacity-70" /> : <Clock size={10} className="shrink-0 opacity-70" />}
        <span className="text-[10px] font-bold truncate tracking-tight">{info.event.title}</span>
      </div>
    );
  };

  return (
    <div className="h-screen w-full bg-[#f8fafc] dark:bg-[#050505] font-sans text-slate-800 dark:text-slate-200 flex flex-col p-6 overflow-hidden gap-6">
      
      {/* 1. ELITE HEADER */}
      <div className="flex-none flex items-center justify-between">
        <div className="flex items-center gap-4">
           {/* Logo / Icon Box */}
           <div className="bg-indigo-600 p-3 rounded-2xl shadow-lg shadow-indigo-500/30 ring-1 ring-indigo-500/50">
              <CalendarIcon className="text-white h-6 w-6" />
           </div>
           
           {/* Date Controls */}
           <div className="flex flex-col">
              <h1 className="text-sm font-bold text-slate-400 uppercase tracking-widest mb-1">Planning Schedule</h1>
              <div className="flex items-center gap-2">
                 {/* Month Select */}
                 <div className="relative group">
                    <select 
                       value={currentDate.getMonth()} 
                       onChange={handleMonthChange}
                       className="appearance-none bg-transparent text-2xl font-black text-slate-900 dark:text-white pr-6 cursor-pointer outline-none hover:text-indigo-600 transition-colors"
                    >
                       {MONTHS.map((m, i) => <option key={i} value={i} className="text-base font-medium">{m}</option>)}
                    </select>
                    <ChevronDown size={14} className="absolute right-0 top-1/2 -translate-y-1/2 text-slate-300 pointer-events-none group-hover:text-indigo-600 transition-colors" />
                 </div>

                 {/* Year Select */}
                 <div className="relative group">
                    <select 
                       value={currentDate.getFullYear()} 
                       onChange={handleYearChange}
                       className="appearance-none bg-transparent text-2xl font-black text-slate-300 dark:text-slate-600 pr-6 cursor-pointer outline-none hover:text-indigo-600 transition-colors"
                    >
                       {Array.from({length: 10}, (_, i) => 2020 + i).map(y => <option key={y} value={y} className="text-base font-medium text-slate-900">{y}</option>)}
                    </select>
                    <ChevronDown size={14} className="absolute right-0 top-1/2 -translate-y-1/2 text-slate-200 pointer-events-none group-hover:text-indigo-600 transition-colors" />
                 </div>
              </div>
           </div>
        </div>

        {/* Right Controls */}
        <div className="flex items-center gap-3 bg-white dark:bg-[#111] p-1.5 rounded-2xl border border-slate-200 dark:border-white/10 shadow-sm">
           <button onClick={handlePrev} className="p-2.5 hover:bg-slate-50 dark:hover:bg-white/5 rounded-xl transition-all text-slate-400 hover:text-slate-900"><ChevronLeft size={20}/></button>
           <button onClick={handleToday} className="px-4 py-2 bg-slate-50 dark:bg-white/5 hover:bg-indigo-50 dark:hover:bg-indigo-900/20 text-xs font-black uppercase tracking-wider text-slate-600 hover:text-indigo-600 rounded-xl transition-all">Today</button>
           <button onClick={handleNext} className="p-2.5 hover:bg-slate-50 dark:hover:bg-white/5 rounded-xl transition-all text-slate-400 hover:text-slate-900"><ChevronRight size={20}/></button>
        </div>
      </div>

      {/* 2. THE CALENDAR GRID */}
      <div className="flex-1 bg-white dark:bg-[#111] rounded-[32px] border border-slate-200 dark:border-white/10 shadow-2xl shadow-slate-200/50 dark:shadow-none overflow-hidden relative p-6">
         
         <FullCalendar
            ref={calendarRef}
            plugins={[dayGridPlugin, interactionPlugin]}
            initialView="dayGridMonth"
            headerToolbar={false}
            events={[...HOLIDAYS, ...MY_LEAVES]}
            eventContent={renderEvent}
            height="100%"
            dayMaxEvents={3}
            fixedWeekCount={false}
            showNonCurrentDates={false}
         />

      </div>

      {/* CSS MAGIC for the "Elite" Look */}
      <style jsx global>{`
        /* 1. Clean Slate */
        .fc {
          --fc-border-color: transparent;
          --fc-page-bg-color: transparent;
          font-family: inherit;
        }

        /* 2. Header Rows (MON, TUE...) */
        .fc-theme-standard th {
            border: none;
        }
        .fc .fc-col-header-cell-cushion {
          padding-bottom: 30px;
          text-transform: uppercase;
          font-size: 0.75rem;
          font-weight: 800;
          color: #94a3b8; /* slate-400 */
          letter-spacing: 0.15em;
        }

        /* 3. The Date Cells */
        .fc-daygrid-day-frame {
          margin: 6px;
          border-radius: 20px; /* Soft rounding */
          padding: 8px;
          border: 1px solid transparent;
          transition: all 0.2s ease-in-out;
          height: 100%;
        }

        /* Hover Effect */
        .fc-daygrid-day:hover .fc-daygrid-day-frame {
          background-color: #f8fafc; /* slate-50 */
          border-color: #e2e8f0; /* slate-200 */
          box-shadow: 0 4px 12px -2px rgba(0, 0, 0, 0.05);
          transform: translateY(-2px);
        }
        .dark .fc-daygrid-day:hover .fc-daygrid-day-frame {
          background-color: rgba(255,255,255,0.03);
          border-color: rgba(255,255,255,0.05);
        }

        /* 4. Weekend Styling (Subtle) */
        .fc-day-sat .fc-daygrid-day-frame, 
        .fc-day-sun .fc-daygrid-day-frame {
          background-color: rgba(248, 250, 252, 0.5); /* Very subtle gray */
        }
        .dark .fc-day-sat .fc-daygrid-day-frame, 
        .dark .fc-day-sun .fc-daygrid-day-frame {
          background-color: rgba(0,0,0,0.2);
        }

        /* 5. Date Numbers */
        .fc-daygrid-day-number {
          font-size: 0.95rem;
          font-weight: 700;
          color: #64748b;
          width: 32px;
          height: 32px;
          display: flex;
          align-items: center;
          justify-content: center;
          border-radius: 12px;
          margin-bottom: 6px;
        }

        /* 6. "Today" Styling (The Glowing Jewel) */
        .fc-day-today .fc-daygrid-day-frame {
          background: linear-gradient(135deg, rgba(79, 70, 229, 0.05), rgba(79, 70, 229, 0.02)) !important;
          border: 1px solid rgba(79, 70, 229, 0.2);
        }
        .fc-day-today .fc-daygrid-day-number {
          background: #4f46e5; /* Indigo 600 */
          color: white;
          box-shadow: 0 4px 10px rgba(79, 70, 229, 0.3);
        }

        /* 7. Hide ugly scrollbars in calendar */
        .fc-scroller::-webkit-scrollbar {
          width: 0px;
          background: transparent;
        }
        
        /* 8. Remove outer table borders completely */
        .fc-theme-standard td, .fc-theme-standard .fc-scrollgrid {
          border: none;
        }
      `}</style>
    </div>
  );
}